Completa la primera línea de la siguiente rutina con una de las cuatro opciones:




CREATE OR REPLACE ------- calcular_pi AS

n NUMBER := 1;

pi NUMBER := 0;

signo NUMBER := 1;

BEGIN

FOR i IN 1..1000000 LOOP

  pi := pi + (signo * (4 / n));

  signo := signo * -1;

  n := n + 2;

END LOOP;

dbms_output.put_line('Valor aproximado de pi: ' || pi);

END;

Completa la primera línea de la siguiente rutina con una de las cuatro opciones:


CREATE OR REPLACE ------- calcular_pi RETURN NUMBER AS

n NUMBER := 1;

pi NUMBER := 0;

signo NUMBER := 1;

BEGIN FOR i IN 1..1000000 LOOP

pi := pi + (signo * (4 / n));

signo := signo * -1;

n := n + 2;

END LOOP;

RETURN pi;

END;

